// @generated by:gauntlet run:godseye-audit-r1-r4
import { readFile } from "node:fs/promises";
import { posix } from "node:path";
import { describe, expect, it } from "vitest";

describe("T39 retained CI browser diagnostics (audit R4)", () => {
  it("archives the configured browser traces and screenshots before workspace cleanup", async () => {
    const [pipeline, config] = await Promise.all([
      readFile("Jenkinsfile", "utf8"),
      readFile("playwright.config.ts", "utf8"),
    ]);
    const outputDir = config.match(/outputDir:\s*["']([^"']+)["']/)?.[1];
    const archive = [...pipeline.matchAll(/archiveArtifacts[^\n]*artifacts:\s*'([^']+)'/g)].at(-1);
    if (!outputDir || !archive || archive.index === undefined)
      throw new Error("Browser output directory or final CI archive declaration missing");
    const patterns = (archive[1] ?? "").split(",");
    const diagnostics = ["failed-journey/trace.zip", "failed-journey/test-failed-1.png"].map(
      (name) => posix.join(outputDir, name),
    );

    expect(
      diagnostics.every((file) => patterns.some((pattern) => posix.matchesGlob(file, pattern))),
    ).toBe(true);
    expect(pipeline.indexOf("deleteDir()", archive.index)).toBeGreaterThan(archive.index);
  });
});
